INSERT INTO feature VALUES('linear-function','calculus','The linear function (x : A) ⊸ C','call-by-push-value','partial','uncommon','dependent provers','A function `def f(x : A) ⊸ C` takes once each parameter that its own list writes, at the multiplicity one. A type reads the parameter freely, and a value read takes its one copy on each path; a read inside a thunk, a recursion or a fold is refused by name. The arrow `(x : A) ⊸ C`, in ASCII `-o`, is its type, and another multiplicity is refused by name.','core-term core-checker core-nbe surface-grammar surface-lowering surface-pretty','corpus/ledger/features/linear-function.gandr corpus/ledger/diagnostics/LinearSlotConsumed.gandr corpus/ledger/diagnostics/LinearSlotUnconsumed.gandr corpus/ledger/diagnostics/ShadowCaptured.gandr','corpus/ledger/features/linear-function.gandr','#5867 #5923');
